describe('Form Data Persistence on Navigation', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should persist form data when navigating away and returning', () => {
    // Fill out form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission success
    cy.intercept('POST', '/api/form-submit').as('formSubmit');
    cy.wait('@formSubmit');
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');

    // Navigate away from the form page
    cy.visit('/dashboard');

    // Verify form data is still present on the form page
    cy.get('[data-testid="name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'john.doe@example.com');
    cy.get('[data-testid="password-input"]').should('have.value', 'SecurePassword123');

    // Return to the form page
    cy.visit('/form-page');

    // Verify form data is still present
    cy.get('[data-testid="name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'john.doe@example.com');
    cy.get('[data-testid="password-input"]').should('have.value', 'SecurePassword123');

    // Verify form is still visible and editable
    cy.get('[data-testid="form-container"]').should('be.visible');
    cy.get('[data-testid="name-input"]').should('be.editable');
  });

  it('should not persist form data when navigating away and returning with invalid data', () => {
    // Fill out form fields with valid data
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane.smith@example.com');
    cy.get('[data-testid="password-input"]').type('ValidPassword123');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission success
    cy.intercept('POST', '/api/form-submit').as('formSubmit');
    cy.wait('@formSubmit');
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');

    // Navigate away from the form page
    cy.visit('/dashboard');

    // Return to the form page with invalid data
    cy.visit('/form-page');

    // Verify form data is cleared
    cy.get('[data-testid="name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="password-input"]').should('have.value', '');

    // Verify form is still visible but empty
    cy.get('[data-testid="form-container"]').should('be.visible');
    cy.get('[data-testid="name-input"]').should('be.editable');
  });
});
